import sys
from math import factorial

MOD = 998244353

def count_distinct_subarrays(n):
    def z_function(s):
        n = len(s)
        z = [0] * n
        l, r = 0, 0
        for i in range(1, n):
            if i <= r:
                z[i] = min(r - i + 1, z[i - l])
            while i + z[i] < n and s[z[i]] == s[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > r:
                l, r = i, i + z[i] - 1
        return z

    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, 0, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

    total_length = n * factorial(n)
    s = ''.join(str(i) for i in range(1, n + 1)) * factorial(n)
    z = z_function(s)

    distinct_subarrays = 0
    for i in range(total_length):
        distinct_subarrays = (distinct_subarrays + total_length - i - z[i]) % MOD

    return distinct_subarrays

n = int(sys.stdin.read().strip())
